// Frostbite settings objects at runtime (GameRenderSettings, WorldRenderSettings, Dx11DisplaySettings, GameTimeSettings).
// The engine caches each settings instance in a static pointer (found from its TypeInfo); field offsets come from the
// game's reflected type data (src/fb_table.inc, generated by tools/gen_fbtable.py).
//   MEAVR\fbsettings.cfg  "Class.Field value" lines, applied once each instance exists (and again on fbset.trigger)
//   MEAVR\fbset.trigger   same format, applied immediately (file deleted)
//   MEAVR\fbdump.trigger  writes every field's current value to MEAVR\fbsettings_dump.txt
#include <windows.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include "fbsettings.h"
#include "globals.h"
#include "log.h"

namespace mea {

struct FbField { const char* name; unsigned off; const char* type; };
struct FbClass { const char* name; unsigned globalRva; const FbField* fields; size_t count; };
#include "fb_table.inc"

static uintptr_t ExeBase() { return (uintptr_t)GetModuleHandleW(nullptr); }

static bool Readable(const void* p, size_t n) {
    MEMORY_BASIC_INFORMATION m{};
    if (!VirtualQuery(p, &m, sizeof(m)) || m.State != MEM_COMMIT || (m.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    return (uintptr_t)p + n <= (uintptr_t)m.BaseAddress + m.RegionSize;
}

// DAI: settings instances come from the engine's settings manager, the way the game code gets them:
// exe+305249F getSettings(*(exe+2916C80), &runtimeTypeInfo) (cached by the game in a static per class, e.g.
// GameRenderSettings at exe+26BF008). Runtime TypeInfo objects (first qword -> TypeInfoData) found in the image.
static const struct { const char* name; unsigned typeInfoRva; unsigned cacheRva; } kTypeInfos[] = {
    {"GameRenderSettings", 0x2DC5F30, 0x26BF008}, {"WorldRenderSettings", 0x2E21280, 0}, {"DA3WorldRenderSettings", 0x2E21340, 0},
    {"GlobalPostProcessSettings", 0x2E10B10, 0}, {"DxDisplaySettings", 0x2E0DB00, 0},
};
typedef void* (__fastcall* PFN_FindSettings)(void* mgr, void* typeInfo);
uint8_t* FbInstance(const char* cls) {
    if (ExeBase() != 0x140000000) return nullptr;
    for (auto& t : kTypeInfos) {
        if (_stricmp(t.name, cls)) continue;
        uint8_t* p = nullptr;
        if (t.cacheRva) { void** g = (void**)(ExeBase() + t.cacheRva); if (Readable(g, 8)) p = (uint8_t*)*g; }
        if (!p) {
            void** mg = (void**)(ExeBase() + 0x2916C80);
            if (!Readable(mg, 8) || !*mg) { static int n = 0; if (n++ < 5) LOGW("fbsettings: settings manager not available"); return nullptr; }
            static std::vector<std::pair<const char*, uint8_t*>> cache;
            for (auto& c : cache) if (c.first == t.name) { p = c.second; break; }
            if (!p) {
                p = (uint8_t*)((PFN_FindSettings)(ExeBase() + 0x305249F))(*mg, (void*)(ExeBase() + t.typeInfoRva));
                if (p) { cache.push_back({t.name, p}); LOGI("fbsettings: %s instance %p", t.name, (void*)p); }
                else { static int n = 0; if (n++ < 10) LOGW("fbsettings: settings manager has no %s instance", t.name); }
            }
        }
        return (p && Readable(p, 0x100)) ? p : nullptr;
    }
    return nullptr;
}

static const FbField* FindField(const FbClass& c, const char* f) {
    for (size_t i = 0; i < c.count; ++i) if (!_stricmp(c.fields[i].name, f)) return &c.fields[i];
    return nullptr;
}

static std::string ValueText(const uint8_t* p, const FbField& f) {
    char b[64];
    const uint8_t* a = p + f.off;
    if (!strcmp(f.type, "B") || !strcmp(f.type, "u8")) snprintf(b, sizeof(b), "%u", *a);
    else if (!strcmp(f.type, "i8")) snprintf(b, sizeof(b), "%d", *(const int8_t*)a);
    else if (!strcmp(f.type, "F")) snprintf(b, sizeof(b), "%g", *(const float*)a);
    else if (!strcmp(f.type, "U")) snprintf(b, sizeof(b), "%u", *(const uint32_t*)a);
    else if (!strcmp(f.type, "u16")) snprintf(b, sizeof(b), "%u", *(const uint16_t*)a);
    else if (!strcmp(f.type, "i16")) snprintf(b, sizeof(b), "%d", *(const int16_t*)a);
    else snprintf(b, sizeof(b), "%d", *(const int32_t*)a);   // I, E
    return b;
}

static void Write(uint8_t* p, const FbField& f, const char* v) {
    uint8_t* a = p + f.off;
    if (!strcmp(f.type, "B")) *a = (uint8_t)(atoi(v) != 0 || !_stricmp(v, "true") || !_stricmp(v, "on"));
    else if (!strcmp(f.type, "u8") || !strcmp(f.type, "i8")) *a = (uint8_t)atoi(v);
    else if (!strcmp(f.type, "F")) *(float*)a = (float)atof(v);
    else if (!strcmp(f.type, "u16") || !strcmp(f.type, "i16")) *(uint16_t*)a = (uint16_t)strtol(v, nullptr, 0);
    else *(int32_t*)a = (int32_t)strtoll(v, nullptr, 0);
}

// "Class.Field value" (Class may be omitted: first class that has the field)
bool FbSet(const char* line) {
    char key[128] = {}, val[64] = {};
    if (sscanf(line, " %127s %63s", key, val) != 2 || key[0] == '#') return false;
    char* dot = strchr(key, '.');
    const char* fieldName = dot ? dot + 1 : key;
    if (dot) *dot = 0;
    for (auto& c : kFbClasses) {
        if (dot && _stricmp(c.name, key)) continue;
        const FbField* f = FindField(c, fieldName);
        if (!f) continue;
        uint8_t* p = FbInstance(c.name);
        if (!p) { LOGW("fb: %s not available yet", c.name); return false; }
        std::string before = ValueText(p, *f);
        Write(p, *f, val);
        LOGI("fb: %s.%s %s -> %s", c.name, f->name, before.c_str(), ValueText(p, *f).c_str());
        return true;
    }
    LOGW("fb: unknown setting '%s%s%s'", dot ? key : "", dot ? "." : "", fieldName);
    return false;
}

std::string FbGet(const char* cls, const char* field) {
    for (auto& c : kFbClasses) {
        if (_stricmp(c.name, cls)) continue;
        const FbField* f = FindField(c, field);
        uint8_t* p = FbInstance(c.name);
        return (f && p) ? ValueText(p, *f) : std::string();
    }
    return {};
}

static void ApplyFile(const std::wstring& path, bool deleteAfter) {
    FILE* f = _wfopen(path.c_str(), L"r");
    if (!f) return;
    char line[256];
    while (fgets(line, sizeof(line), f)) FbSet(line);
    fclose(f);
    if (deleteAfter) DeleteFileW(path.c_str());
}

static void Dump() {
    std::wstring path = G().outDir + L"fbsettings_dump.txt";
    FILE* f = _wfopen(path.c_str(), L"w");
    if (!f) return;
    for (auto& c : kFbClasses) {
        uint8_t* p = FbInstance(c.name);
        fprintf(f, "# %s at %p (static pointer exe+%X)\n", c.name, (void*)p, c.globalRva);
        if (!p) continue;
        for (size_t i = 0; i < c.count; ++i) fprintf(f, "%s.%s %s\n", c.name, c.fields[i].name, ValueText(p, c.fields[i]).c_str());
    }
    fclose(f);
    LOGI("fb: settings dumped to %S", path.c_str());
}

void FbOnPresent(uint64_t presentIndex) {
    static bool startupApplied = false;
    if (!startupApplied && (presentIndex % 30) == 7 && FbInstance("GameRenderSettings") && FbInstance("Dx11DisplaySettings")) {
        startupApplied = true;
        for (auto& c : kFbClasses) LOGI("fb: %s instance %p", c.name, (void*)FbInstance(c.name));
        ApplyFile(G().outDir + L"fbsettings.cfg", false);
    }
    if ((presentIndex % 30) != 21) return;
    std::wstring t = G().outDir + L"fbset.trigger";
    if (GetFileAttributesW(t.c_str()) != INVALID_FILE_ATTRIBUTES) ApplyFile(t, true);
    t = G().outDir + L"fbdump.trigger";
    if (GetFileAttributesW(t.c_str()) != INVALID_FILE_ATTRIBUTES) { DeleteFileW(t.c_str()); Dump(); }
}

} // namespace mea
